from __future__ import annotations
import math
from collections import defaultdict
from typing import Callable, Dict, Hashable, List

BOLTZMANN_K: float = 1.380_649e-23

def shannon_entropy(p: Dict[Hashable, float]) -> float:
    return -sum(px * math.log(px) for px in p.values() if px > 0.0)

def pushforward(f: Callable[[Hashable], Hashable],
                p: Dict[Hashable, float]) -> Dict[Hashable, float]:
    out: Dict[Hashable, float] = defaultdict(float)
    for x, px in p.items():
        out[f(x)] += px
    return dict(out)

def bitstrings(n: int) -> List[str]:
    return [format(i, f'0{n}b') for i in range(2 ** n)]

def one_bit_erasure_costs(max_n: int = 5, temperature: float = 300.0) -> None:
    erase_all: Callable[[Hashable], Hashable] = lambda s: '0' * len(s)
    print(f'predicted kT ln 2 (T={temperature}K): '
          f'{BOLTZMANN_K * temperature * math.log(2):.6e} J')
    for n in range(1, max_n + 1):
        p = {s: 1.0 / 2 ** n for s in bitstrings(n)}
        fp = pushforward(erase_all, p)
        W = BOLTZMANN_K * temperature * (shannon_entropy(p) - shannon_entropy(fp))
        predicted = n * BOLTZMANN_K * temperature * math.log(2)
        print(f'n={n}: W={W:.6e} J  matches n*kTln2 ? '
              f'{abs(W - predicted) < 1e-30}')

if __name__ == '__main__':
    one_bit_erasure_costs()

