function PUSHFORWARD(f, p):            # f : alpha -> beta, p : alpha -> R>=0
    out <- empty map with default 0.0
    for each x in domain(p):
        out[f(x)] <- out[f(x)] + p(x)  # x lies in its own fiber over f(x)
    return out                          # out[y] = sum_{x : f(x)=y} p(x)

